template.css:
html, body {
  margin: 0;
  padding: 0;
  font-family: Arial, Helvetica, sans-serif;
  color: #000;
}
.label {
  box-sizing: border-box;
  width: 70mm;
  height: 50mm;
  padding: 2.5mm 2.8mm 2mm;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.media {
  display: flex;
  gap: 2.5mm;
  min-height: 0;
}
img.product {
  width: 18mm;
  height: 18mm;
  object-fit: cover;
  border: 0.2mm solid #111;
  flex: 0 0 auto;
}
img.product[src=""] {
  display: none;
}
.info {
  flex: 1 1 auto;
  min-width: 0;
}
.name {
  font-size: 13px;
  font-weight: 700;
  line-height: 1.2;
  max-height: 2.4em;
  overflow: hidden;
}
.prices {
  margin-top: 1.4mm;
  display: flex;
  align-items: baseline;
  gap: 1.8mm;
}
.old {
  text-decoration: line-through;
  font-size: 11px;
  color: #555;
}
.now {
  font-size: 20px;
  font-weight: 800;
  line-height: 1;
  letter-spacing: -0.02em;
}
.currency {
  font-size: 11px;
  font-weight: 700;
}
.meta {
  font-size: 9px;
  margin-top: 1mm;
  color: #444;
}
.barcode-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5mm;
  margin-top: auto;
  width: 100%;
}
img.barcode {
  height: 15mm;
  width: 100%;
  max-width: 100%;
  object-fit: contain;
  object-position: center bottom;
}
.code {
  font-size: 11.5px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-align: center;
  white-space: nowrap;
}
